#include "tgcloud/sync/crypto.hpp"
#include <openssl/evp.h>
#include <random>
#include <stdexcept>
#include <cstring>
namespace tgcloud::sync { std::string encrypt(std::string_view in,std::string_view pw){unsigned char salt[16],iv[12],key[32];std::random_device r;for(auto&x:salt)x=r();for(auto&x:iv)x=r();PKCS5_PBKDF2_HMAC(pw.data(),pw.size(),salt,16,100000,EVP_sha256(),32,key);EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();EVP_EncryptInit_ex(c,EVP_aes_256_gcm(),nullptr,key,iv);std::string e(in.size()+16,0);int n=0,z=0;EVP_EncryptUpdate(c,(unsigned char*)e.data(),&n,(const unsigned char*)in.data(),in.size());EVP_EncryptFinal_ex(c,(unsigned char*)e.data()+n,&z);unsigned char tag[16];EVP_CIPHER_CTX_ctrl(c,EVP_CTRL_GCM_GET_TAG,16,tag);EVP_CIPHER_CTX_free(c);std::string o="SYNC1";o.append((char*)salt,16);o.append((char*)iv,12);o.append(e.data(),n+z);o.append((char*)tag,16);return o;}std::string decrypt(std::string_view b,std::string_view pw){if(b.size()<49||b.substr(0,5)!="SYNC1")throw std::runtime_error("invalid sync envelope");unsigned char key[32];PKCS5_PBKDF2_HMAC(pw.data(),pw.size(),(const unsigned char*)b.data()+5,16,100000,EVP_sha256(),32,key);EVP_CIPHER_CTX*c=EVP_CIPHER_CTX_new();EVP_DecryptInit_ex(c,EVP_aes_256_gcm(),nullptr,key,(const unsigned char*)b.data()+21);int n=0,z=0;std::string p(b.size()-49,0);EVP_DecryptUpdate(c,(unsigned char*)p.data(),&n,(const unsigned char*)b.data()+33,b.size()-49);EVP_CIPHER_CTX_ctrl(c,EVP_CTRL_GCM_SET_TAG,16,(void*)(b.data()+b.size()-16));if(EVP_DecryptFinal_ex(c,(unsigned char*)p.data()+n,&z)<=0){EVP_CIPHER_CTX_free(c);throw std::runtime_error("sync authentication failed");}EVP_CIPHER_CTX_free(c);p.resize(n+z);return p;}}
